<section class="detail-summary detail-card" aria-label="Reservation summary">
    <div class="detail-summary-event"><span>Event Name</span><strong>{{ $reservation->event_name }}</strong><div><span class="detail-event-type">{{ $reservation->event_type ?: $reservation->event_name }}</span><span class="detail-summary-type">{{ ucwords(str_replace('_', ' ', $reservation->reservation_type)) }}</span></div></div>
    <div><i class="bi bi-calendar3" aria-hidden="true"></i><div><span>Date</span><p>{{ $reservation->reservation_date->format('F d, Y') }} <span class="detail-day">{{ $reservation->reservation_date->format('l') }}</span></p></div></div>
    <div><i class="bi bi-clock" aria-hidden="true"></i><div><span>Time</span><p>{{ $startLabel }} – {{ $endLabel }}</p><small>({{ $durationLabel }})</small></div></div>
    <div><i class="bi bi-geo-alt" aria-hidden="true"></i><div><span>Facility</span><p>{{ $reservation->facility->facility_name ?? 'Not assigned' }}</p></div></div>
    <div><i class="bi bi-people" aria-hidden="true"></i><div><span>Expected Attendees</span><p><strong>{{ number_format($reservation->expected_attendees) }}</strong></p><small>Gym Capacity: {{ number_format(\App\Support\GymCapacity::MAX_ATTENDEES) }}</small><div class="detail-capacity-value"><div class="detail-capacity-track" role="meter" aria-label="Capacity usage" aria-valuemin="0" aria-valuemax="{{ \App\Support\GymCapacity::MAX_ATTENDEES }}" aria-valuenow="{{ $reservation->expected_attendees }}"><span style="width:{{ min(100, max(0, $capacityUsage)) }}%"></span></div><span>{{ number_format($capacityUsage, 1) }}%</span></div></div></div>
</section>
